WITH oracle_1 AS (WITH scoped AS (SELECT q.mktcode,q.tgtcode,q.bizdate,(q.lastPx/10000.0)*q.totalShare AS metric FROM `newzl`.`hsj_stock_hq_basic` q WHERE q.bizdate='2026-04-14' AND (q.mktcode=1 AND q.tgtcode BETWEEN '688000' AND '688999')), industry_stat AS (SELECT i.industry_code,MIN(s.metric) AS baseline FROM scoped s INNER JOIN `findsl_ext`.`industry_membership` i ON i.mktcode=s.mktcode AND i.tgtcode=s.tgtcode WHERE i.snapshot_id='baostock-industry-2026-07-13-4d38e6963e35' AND i.classification_system='证监会行业分类' AND i.industry_level='industry' GROUP BY i.industry_code) SELECT s.mktcode,s.tgtcode,s.bizdate FROM scoped s INNER JOIN `findsl_ext`.`industry_membership` i ON i.mktcode=s.mktcode AND i.tgtcode=s.tgtcode INNER JOIN industry_stat a ON a.industry_code=i.industry_code WHERE i.snapshot_id='baostock-industry-2026-07-13-4d38e6963e35' AND i.classification_system='证监会行业分类' AND i.industry_level='industry' AND s.metric>a.baseline), branch_1 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_1 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=0 AND q.volume>=10), oracle_2 AS (WITH ranked AS (SELECT b.mktcode,b.tgtcode,b.bizdate,ROW_NUMBER() OVER (ORDER BY b.volume DESC,b.mktcode ASC,b.tgtcode ASC) AS rn,COUNT(*) OVER () AS population FROM `newzl`.`hsj_stock_hq_basic` AS b WHERE b.bizdate='2026-04-14') SELECT mktcode,tgtcode,bizdate FROM ranked WHERE rn<=10), branch_2 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_2 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE 1=1 AND q.volume>=1000), oracle_3 AS (SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` AS t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate WHERE b.bizdate='2026-04-14' AND ABS(b.lastPx/10000.0-t.ma20)/NULLIF(ABS(t.ma20),0)<=0.02 AND b.lastPx/10000.0>=t.ma20*0.995), branch_3 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_3 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=0 AND q.volume>=1), nested_pair AS (SELECT l.mktcode,l.tgtcode,l.bizdate FROM branch_1 l INNER JOIN branch_2 r ON r.mktcode=l.mktcode AND r.tgtcode=l.tgtcode AND r.bizdate=l.bizdate) SELECT mktcode,tgtcode,bizdate FROM nested_pair UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM branch_3;
